import type { TestDef } from './types';
import { PSYCHOMETRIC_REAL_FORMAT_MOCKS } from './tests-psychometric-real';

// ─────────────────────────────────────────────────────────────────────────
// Psychometric Test Preparation: four general practice mocks (numerical,
// verbal, abstract/logical, public service judgment). Not tied to one job
// posting. All questions are original practice material written for JobPrep;
// they are not real or past exam papers and do not come from MIFOTRA.
// Every name, figure and table in these questions is invented for practice.
//
// Sources checked for the Rwandan rules cited in Mock 4 (only the points below
// are relied on; every other Mock 4 scenario rests on general ethics):
// - Presidential Order N° 021/01 of 24/02/2021 determining professional ethics
//   for public servants, Official Gazette n° Special of 25/02/2021, read in the
//   gazette text for Articles 5-10, 12, 13, 15-17 and 28-30:
//   https://www.mifotra.gov.rw/fileadmin/user_upload/Mifotra/Publication/4.PRESIDENTIAL_ORDERS/Imyitwarire_mbonezamurimo_ku_Bakozi_ba_Leta_2021.pdf
//   https://rwandalii.org/akn/rw/act/po/2021/21/eng@2021-02-25
// - Law N° 55/2021 of 29/08/2021 on declaration of assets, Official Gazette
//   n° 32 ter of 30/08/2021, read for Articles 2, 3, 9 and 12:
//   https://commons.laws.africa/akn/rw/act/law/2021/55/media/publication/rw-act-law-2021-55-publication-document.pdf
// ─────────────────────────────────────────────────────────────────────────

const PROFESSION = { slug: 'psychometric-test-preparation', name: 'Psychometric Test Preparation' };
const CATEGORY = 'other-professional';

// ───────────────────────────── Mock 1: Numerical reasoning

const NUM1 = 'Percentages and ratios';
const NUM2 = 'Averages and budgets';
const NUM3 = 'Data interpretation';

const psychometricPrepMock1: TestDef = {
  country: 'RW',
  category: CATEGORY,
  profession: PROFESSION,
  slug: 'psychometric-test-preparation-mock-1',
  title: 'Psychometric Test Preparation — Mock Exam 1: Numerical Reasoning',
  summary: 'Original practice questions on percentages, ratios, averages, RWF budgets and reading small data tables. For practice only: this is not a real or past exam paper.',
  free: true,
  difficulty: 'STANDARD',
  minutes: 90,
  sections: [{ name: NUM1 }, { name: NUM2 }, { name: NUM3 }],
  questions: [
    { section: NUM1, topic: NUM1, stem: 'A district office has 240 staff, and 35% of them attended a training course. How many staff did not attend?', options: ['84', '144', '156', '164'], correct: 2, explanation: '100% − 35% = 65% did not attend. 65% × 240 = 156. (84 is the number who did attend.)' },
    { section: NUM1, topic: NUM1, stem: 'A monthly salary of RWF 320,000 rises by 12.5%. What is the new salary?', options: ['RWF 360,000', 'RWF 352,000', 'RWF 332,500', 'RWF 400,000'], correct: 0, explanation: '12.5% × 320,000 = 40,000. New salary = 320,000 + 40,000 = RWF 360,000.' },
    { section: NUM1, topic: NUM1, stem: 'After a 20% discount, a printer costs RWF 48,000. What was the price before the discount?', options: ['RWF 57,600', 'RWF 38,400', 'RWF 68,000', 'RWF 60,000'], correct: 3, explanation: 'The discounted price is 80% of the original. Original = 48,000 ÷ 0.80 = RWF 60,000. (Adding 20% to 48,000 gives 57,600, which uses the wrong base.)' },
    { section: NUM1, topic: NUM1, stem: 'Applications for a post rose from 1,250 last year to 1,500 this year. What is the percentage increase?', options: ['16.7%', '20%', '25%', '12.5%'], correct: 1, explanation: 'Increase = 1,500 − 1,250 = 250. Percentage increase = 250 ÷ 1,250 = 0.20 = 20%. (16.7% wrongly divides by the new figure, 1,500.)' },
    { section: NUM1, topic: NUM1, stem: 'A grant of RWF 4,800,000 is shared between two Sectors in the ratio 5:3. What is the larger share?', options: ['RWF 1,800,000', 'RWF 2,400,000', 'RWF 3,000,000', 'RWF 3,200,000'], correct: 2, explanation: 'Total parts = 5 + 3 = 8. One part = 4,800,000 ÷ 8 = 600,000. Larger share = 5 × 600,000 = RWF 3,000,000.' },
    { section: NUM1, topic: NUM1, stem: 'The ratio of men to women in a project team is 7:4. If there are 28 men, how many people are in the team altogether?', options: ['44', '32', '48', '52'], correct: 0, explanation: 'One part = 28 ÷ 7 = 4. Women = 4 × 4 = 16. Team total = 28 + 16 = 44.' },
    { section: NUM1, topic: NUM1, stem: 'Three schools share 1,260 textbooks in the ratio 2:3:4. How many more textbooks does the school with the largest share receive than the school with the smallest share?', options: ['140', '420', '560', '280'], correct: 3, explanation: 'Total parts = 2 + 3 + 4 = 9. One part = 1,260 ÷ 9 = 140. Difference = (4 − 2) parts = 2 × 140 = 280.' },
    { section: NUM1, topic: NUM1, stem: 'A price rises by 25% and the new price then falls by 20%. How does the final price compare with the original price?', options: ['5% higher', 'No change', '5% lower', '1% lower'], correct: 1, explanation: 'Take an original price of 100. After the rise: 100 × 1.25 = 125. After the fall: 125 × 0.80 = 100. The final price equals the original price.' },
    { section: NUM1, topic: NUM1, stem: 'A supplier adds 18% tax to the net price of an order, and the invoice total is RWF 236,000. How much of the invoice total is tax?', options: ['RWF 42,480', 'RWF 36,000', 'RWF 18,000', 'RWF 200,000'], correct: 1, explanation: 'The total is 118% of the net price, so net price = 236,000 ÷ 1.18 = 200,000. Tax = 236,000 − 200,000 = RWF 36,000. (42,480 wrongly takes 18% of the total.)' },
    { section: NUM1, topic: NUM1, stem: 'Of 450 candidates in a test, 60% are women, and 40% of the women passed. How many women passed?', options: ['108', '180', '162', '72'], correct: 0, explanation: 'Women = 60% × 450 = 270. Women who passed = 40% × 270 = 108.' },

    { section: NUM2, topic: NUM2, stem: 'Five officers closed 42, 38, 51, 45 and 44 files in a month. What is the mean number of files closed per officer?', options: ['43', '44', '45', '46'], correct: 1, explanation: 'Sum = 42 + 38 + 51 + 45 + 44 = 220. Mean = 220 ÷ 5 = 44.' },
    { section: NUM2, topic: NUM2, stem: 'The mean score of 8 candidates is 65. A ninth candidate then scores 92. What is the new mean score of all 9 candidates?', options: ['78.5', '70', '66', '68'], correct: 3, explanation: 'Total of the first 8 = 8 × 65 = 520. New total = 520 + 92 = 612. New mean = 612 ÷ 9 = 68.' },
    { section: NUM2, topic: NUM2, stem: 'A unit’s monthly budget is RWF 2,400,000: 45% goes to salaries, 30% to fieldwork, and the rest is split equally between fuel and stationery. How much is allocated to fuel?', options: ['RWF 300,000', 'RWF 600,000', 'RWF 360,000', 'RWF 240,000'], correct: 0, explanation: 'Remainder = 100% − 45% − 30% = 25%. 25% × 2,400,000 = 600,000. Fuel is half of that: 600,000 ÷ 2 = RWF 300,000.' },
    { section: NUM2, topic: NUM2, stem: 'A team of 12 people has a mean monthly transport cost of RWF 18,000 per person. Three members who each spend RWF 30,000 leave the team. What is the mean monthly cost for the remaining 9?', options: ['RWF 12,000', 'RWF 14,000', 'RWF 15,000', 'RWF 16,000'], correct: 1, explanation: 'Team total = 12 × 18,000 = 216,000. Leavers’ total = 3 × 30,000 = 90,000. Remaining total = 216,000 − 90,000 = 126,000. New mean = 126,000 ÷ 9 = RWF 14,000.' },
    { section: NUM2, topic: NUM2, stem: 'A workshop has 35 participants for 3 days. Meals cost RWF 12,500 per participant per day, and the hall costs RWF 450,000 for the whole workshop. What is the total cost?', options: ['RWF 887,500', 'RWF 1,312,500', 'RWF 1,762,500', 'RWF 2,662,500'], correct: 2, explanation: 'Meals = 35 × 12,500 × 3 = 1,312,500. Total = 1,312,500 + 450,000 = RWF 1,762,500. (887,500 counts meals for one day only; 2,662,500 wrongly pays for the hall three times.)' },
    { section: NUM2, topic: NUM2, stem: 'An institution with an annual budget of RWF 96,000,000 has spent 58% of it. How much remains?', options: ['RWF 40,320,000', 'RWF 55,680,000', 'RWF 38,400,000', 'RWF 42,000,000'], correct: 0, explanation: 'Remaining = 100% − 58% = 42%. 42% × 96,000,000 = RWF 40,320,000. (55,680,000 is the amount already spent.)' },
    { section: NUM2, topic: NUM2, stem: 'A vehicle uses 12 litres of fuel per 100 km. At RWF 1,800 per litre, what is the fuel cost of a 350 km journey?', options: ['RWF 64,800', 'RWF 72,000', 'RWF 86,400', 'RWF 75,600'], correct: 3, explanation: 'Fuel used = 350 ÷ 100 × 12 = 42 litres. Cost = 42 × 1,800 = RWF 75,600.' },
    { section: NUM2, topic: NUM2, stem: 'An officer is owed RWF 30,000 per night for 4 nights, plus a single transport payment of RWF 25,000. An advance of RWF 100,000 has already been paid. What balance is still due?', options: ['RWF 45,000', 'RWF 20,000', 'RWF 145,000', 'RWF 75,000'], correct: 0, explanation: 'Amount owed = (4 × 30,000) + 25,000 = 145,000. Balance = 145,000 − 100,000 = RWF 45,000.' },
    { section: NUM2, topic: NUM2, stem: 'A written paper counts for 60% of a final mark and an oral paper for 40%. A candidate scores 70 in the written paper and 85 in the oral paper. What is the final mark?', options: ['76', '77.5', '74', '78'], correct: 0, explanation: 'Final mark = (0.60 × 70) + (0.40 × 85) = 42 + 34 = 76. (77.5 is the simple mean, which ignores the weights.)' },
    { section: NUM2, topic: NUM2, stem: 'A candidate needs a mean of 70 across 4 papers and has scored 62, 74 and 68 on the first three. What score is needed on the fourth paper?', options: ['70', '72', '76', '80'], correct: 2, explanation: 'Total needed = 4 × 70 = 280. Scored so far = 62 + 74 + 68 = 204. Fourth paper = 280 − 204 = 76.' },

    { section: NUM3, topic: NUM3, stem: 'Table: files closed by a unit. Q1 = 120; Q2 = 150; Q3 = 90; Q4 = 180. What percentage of the year’s files were closed in Q4, to one decimal place?', options: ['25.0%', '30.0%', '33.3%', '36.0%'], correct: 2, explanation: 'Year total = 120 + 150 + 90 + 180 = 540. Q4 share = 180 ÷ 540 = 0.333 = 33.3%.' },
    { section: NUM3, topic: NUM3, stem: 'Table: budget and spending in RWF million. Health: budget 40, spent 34. Education: budget 60, spent 57. Water: budget 25, spent 20. Roads: budget 75, spent 60. Which area spent the highest percentage of its budget?', options: ['Health', 'Water', 'Education', 'Roads'], correct: 2, explanation: 'Health 34 ÷ 40 = 85%. Education 57 ÷ 60 = 95%. Water 20 ÷ 25 = 80%. Roads 60 ÷ 75 = 80%. Education is highest. (Roads spent the most money, but not the highest percentage.)' },
    { section: NUM3, topic: NUM3, stem: 'Table: clinic visits. January = 400; February = 460; March = 437; April = 500. Between which two consecutive months was the percentage change largest, up or down?', options: ['March to April', 'January to February', 'February to March', 'The changes are all equal'], correct: 1, explanation: 'January to February: 60 ÷ 400 = 15%. February to March: 23 ÷ 460 = 5%. March to April: 63 ÷ 437 ≈ 14.4%. January to February is largest, even though March to April has the largest change in number of visits.' },
    { section: NUM3, topic: NUM3, stem: 'Table: test results. District A: 200 sat, 50 passed. District B: 160 sat, 48 passed. District C: 250 sat, 55 passed. District D: 120 sat, 30 passed. Which district has the highest pass rate?', options: ['District A', 'District C', 'District D', 'District B'], correct: 3, explanation: 'A 50 ÷ 200 = 25%. B 48 ÷ 160 = 30%. C 55 ÷ 250 = 22%. D 30 ÷ 120 = 25%. District B is highest. (District C has the most passes, but the lowest rate.)' },
    { section: NUM3, topic: NUM3, stem: 'Table: households with piped water, out of all households. Cell P: 300 of 400. Cell Q: 210 of 300. Cell R: 150 of 250. Cell S: 270 of 300. What percentage of all households in the four Cells together have piped water?', options: ['73.75%', '74.4%', '75.0%', '80.0%'], correct: 1, explanation: 'With water = 300 + 210 + 150 + 270 = 930. All households = 400 + 300 + 250 + 300 = 1,250. 930 ÷ 1,250 = 74.4%. (73.75% averages the four Cell rates, ignoring that the Cells differ in size.)' },
    { section: NUM3, topic: NUM3, stem: 'Table: monthly spending in RWF thousand. Salaries = 1,800; Fuel = 450; Stationery = 150; Maintenance = 600. What is the ratio of fuel to maintenance spending in its simplest form?', options: ['3:4', '4:3', '1:4', '3:8'], correct: 0, explanation: 'Fuel : maintenance = 450 : 600. Dividing both by 150 gives 3:4.' },
    { section: NUM3, topic: NUM3, stem: 'Table: staff by role. Officers = 18; Assistants = 27; Drivers = 9; Others = 6. If this were drawn as a pie chart, how many degrees would the Assistants’ slice measure?', options: ['27°', '108°', '162°', '180°'], correct: 2, explanation: 'Total staff = 18 + 27 + 9 + 6 = 60. Assistants’ share = 27 ÷ 60 = 0.45. 0.45 × 360° = 162°.' },
    { section: NUM3, topic: NUM3, stem: 'Table: enrolment on a training programme. Year 1 = 1,600; Year 2 = 1,840; Year 3 = 2,208. By what percentage did enrolment grow from Year 2 to Year 3?', options: ['15%', '23%', '38%', '20%'], correct: 3, explanation: 'Increase = 2,208 − 1,840 = 368. Growth = 368 ÷ 1,840 = 0.20 = 20%. (23% wrongly divides by Year 1; 15% is the growth from Year 1 to Year 2.)' },
    { section: NUM3, topic: NUM3, stem: 'Table: an order of office supplies (unit price in RWF, quantity). Pens: 300, 200. Notebooks: 1,500, 50. Folders: 800, 75. Markers: 1,200, 25. What is the total value of the order?', options: ['RWF 195,000', 'RWF 210,000', 'RWF 240,000', 'RWF 225,000'], correct: 3, explanation: 'Pens 300 × 200 = 60,000. Notebooks 1,500 × 50 = 75,000. Folders 800 × 75 = 60,000. Markers 1,200 × 25 = 30,000. Total = 60,000 + 75,000 + 60,000 + 30,000 = RWF 225,000.' },
    { section: NUM3, topic: NUM3, stem: 'Table: planned and actual spending in RWF thousand. January: 500 planned, 550 actual. February: 500 planned, 470 actual. March: 600 planned, 630 actual. April: 400 planned, 360 actual. Over the four months together, what was the position against plan?', options: ['Underspent by RWF 10,000', 'Overspent by RWF 10,000', 'Overspent by RWF 20,000', 'Exactly on plan'], correct: 1, explanation: 'Planned = 500 + 500 + 600 + 400 = 2,000 thousand. Actual = 550 + 470 + 630 + 360 = 2,010 thousand. Actual exceeds plan by 10 thousand, so the overspend is RWF 10,000.' },
  ],
};

// ───────────────────────────── Mock 2: Verbal reasoning

const VER1 = 'Reading and inference';
const VER2 = 'Analogies and sentence logic';
const VER3 = 'Vocabulary in context';

const psychometricPrepMock2: TestDef = {
  country: 'RW',
  category: CATEGORY,
  profession: PROFESSION,
  slug: 'psychometric-test-preparation-mock-2',
  title: 'Psychometric Test Preparation — Mock Exam 2: Verbal Reasoning',
  summary: 'Original practice questions on true, false and cannot-say inference from short passages, analogies, sentence logic and vocabulary in context. For practice only: this is not a real or past exam paper.',
  free: false,
  difficulty: 'STANDARD',
  minutes: 90,
  sections: [{ name: VER1 }, { name: VER2 }, { name: VER3 }],
  questions: [
    { section: VER1, topic: VER1, stem: 'A district introduced an online form for business permits in March. That month, 420 applications came in online and 180 on paper. Officers felt that online applications needed fewer corrections, but they kept no figures on this. Based only on the passage, which statement is TRUE?', options: ['Most applications that month were submitted online.', 'Online applications were processed faster than paper ones.', 'Paper applications were no longer accepted in March.', 'Officers recorded how many corrections each application needed.'], correct: 0, explanation: '420 of 600 applications were online, so the first statement is true. Processing speed is not mentioned (cannot say). The 180 paper applications contradict the third statement, and the passage says no figures were kept, which contradicts the fourth.' },
    { section: VER1, topic: VER1, stem: 'A cooperative sells its coffee to two buyers. Last season Buyer A paid more per kilogram than Buyer B, but Buyer A charged for transport, while Buyer B collected the coffee free of charge. The cooperative sold more coffee to Buyer B. Based only on the passage, which statement CANNOT be determined?', options: ['Buyer A paid a higher price per kilogram.', 'The cooperative sold less coffee to Buyer A than to Buyer B.', 'Selling to Buyer B earned more per kilogram after transport.', 'Buyer A charged the cooperative for transport.'], correct: 2, explanation: 'The passage gives neither the prices nor the transport charge, so net income per kilogram cannot be worked out. The other three statements are all stated directly.' },
    { section: VER1, topic: VER1, stem: 'Only officers who have completed the data-protection course have access to the archive. Alice has access to the archive. Jean has completed the course but has not yet been given access. Based only on the passage, which statement is FALSE?', options: ['Alice has completed the data-protection course.', 'Jean does not currently have access to the archive.', 'Officers receive access within a month of completing the course.', 'Some officer has access without having completed the course.'], correct: 3, explanation: 'The word “only” rules out access without the course, so the last statement contradicts the passage. Alice must have completed the course (true), Jean has no access yet (true), and the time taken to receive access is not given (cannot say, rather than false).' },
    { section: VER1, topic: VER1, stem: 'The road linking two Sectors closes whenever the river rises above the bridge deck. The river rose above the bridge deck twice in April. In May the road was closed for one week for repairs. Based only on the passage, which statement is TRUE?', options: ['High water is the only reason this road ever closes.', 'The road was closed on at least one occasion in April.', 'The river stayed below the bridge deck throughout May.', 'Each closure in April lasted for one week.'], correct: 1, explanation: 'The road closes whenever the river rises above the deck, and that happened in April, so the second statement is true. The May repairs contradict the first. The river’s level in May and the length of the April closures are not given (cannot say).' },
    { section: VER1, topic: VER1, stem: 'A staff survey was sent to all 150 employees of a public institution, and 60 replied. Of those who replied, 80% said they were satisfied with internal communication. Based only on the passage, which statement CANNOT be determined?', options: ['Forty per cent of employees replied to the survey.', 'Forty-eight employees said that they were satisfied with internal communication.', 'Most employees are satisfied with internal communication.', 'The survey went to more people than replied to it.'], correct: 2, explanation: '60 ÷ 150 = 40% replied, and 80% × 60 = 48 said they were satisfied. The views of the 90 who did not reply are unknown, so satisfaction among all employees cannot be determined. The fourth statement is true (150 is more than 60).' },
    { section: VER1, topic: VER1, stem: 'A public library opens from Monday to Saturday and is closed on public holidays. On Saturdays it closes at 1 p.m.; on other open days it closes at 5 p.m. Based only on the passage, which statement is FALSE?', options: ['The library stays open until 5 p.m. on Saturdays.', 'The library is closed on Sundays.', 'If a public holiday falls on a Wednesday, the library is closed that day.', 'More people visit the library on Saturdays than on Mondays.'], correct: 0, explanation: 'The passage says Saturday closing is at 1 p.m., so the first statement is false. The next two statements follow from the passage. Visitor numbers are not mentioned, so the last statement is cannot say, not false.' },
    { section: VER1, topic: VER1, stem: 'A Sector’s rules say that any activity costing more than RWF 500,000 needs the Executive Secretary’s approval. The water-tank repair cost RWF 620,000 and the school fence cost RWF 450,000. Based only on the passage, which statement is TRUE?', options: ['The Executive Secretary did not approve the school fence.', 'Every activity in the Sector needs the Executive Secretary’s approval.', 'The water-tank repair was finished on time.', 'The water-tank repair needed the Executive Secretary’s approval.'], correct: 3, explanation: 'RWF 620,000 is more than RWF 500,000, so the repair needed approval. The rule only covers activities above RWF 500,000, so it does not support the claim about every activity. The passage does not say whether the fence was approved, or when the repair finished (cannot say).' },
    { section: VER1, topic: VER1, stem: 'After a health centre installed a new queue system, its average waiting time fell from 50 minutes to 30 minutes. The manager concluded that the queue system caused the fall. Which statement, if true, most weakens the manager’s conclusion?', options: ['Patients say they prefer the new system to the old one.', 'Two additional nurses began work at the centre in the same week.', 'The queue system cost more than the manager had expected.', 'Other health centres plan to install a similar system next year.'], correct: 1, explanation: 'Extra nurses starting at the same time offer another explanation for the shorter waits, which weakens the claim that the queue system caused the fall. The other statements concern preference, cost and future plans, and say nothing about the cause.' },
    { section: VER1, topic: VER1, stem: 'Community meetings work better when residents receive the agenda in advance. Knowing the topics, they can consult neighbours, bring documents and prepare questions. Leaders, in turn, spend less time on basic explanations and more on decisions. Which statement best expresses the main point of the passage?', options: ['Sharing the agenda in advance makes community meetings more productive.', 'Leaders should stop explaining basic matters at community meetings.', 'Residents must bring documents to every community meeting.', 'Community meetings should be shorter than they are now.'], correct: 0, explanation: 'The first sentence states the point, and the rest gives reasons for it. The other statements either turn a detail into a rule or, in the case of meeting length, go beyond the passage.' },
    { section: VER1, topic: VER1, stem: 'A resident argues: “The Sector should display its official service fees on the notice board, so that people stop being overcharged.” Which assumption does this argument depend on?', options: ['Every officer in the Sector overcharges residents.', 'Residents prefer notice boards to any other source of information.', 'People who know the official fee are less likely to pay more than it.', 'Notice boards cost less to maintain than radio announcements.'], correct: 2, explanation: 'Displaying fees can only reduce overcharging if knowing the official fee helps people avoid paying more. The argument does not need every officer to overcharge, nor does it compare notice boards with other channels.' },
    { section: VER1, topic: VER1, stem: 'A tender’s rules state: late bids are rejected, unsigned bids are rejected, and all other bids go to evaluation. Bid X arrived late and was signed. Bid Y arrived on time and was unsigned. Bid Z arrived on time and was signed. Which statement must be true?', options: ['Bid Z will win the tender.', 'Only Bid Z goes to evaluation.', 'Bids X and Z go to evaluation.', 'All three bids are rejected.'], correct: 1, explanation: 'X is rejected for lateness and Y for having no signature, while Z meets both conditions, so only Z goes to evaluation. Going to evaluation does not guarantee winning, so the first statement need not be true.' },
    { section: VER1, topic: VER1, stem: 'Kayitesi joined the unit in 2019, two years before Mugisha. Mugisha was promoted in 2023. Kayitesi has not been promoted since joining. Based only on the passage, which statement CANNOT be determined?', options: ['Mugisha joined the unit in 2021.', 'Kayitesi joined the unit before Mugisha did.', 'Mugisha had been in the unit for about two years when he was promoted.', 'Mugisha was promoted because his performance was better than Kayitesi’s.'], correct: 3, explanation: 'The passage gives no reason for the promotion, so the last statement cannot be determined. The first three follow from the dates: 2019 + 2 = 2021, and 2021 to 2023 is about two years.' },
    { section: VER1, topic: VER1, stem: 'Of 40 trainees, 25 come from the Northern Province and the rest from the Southern Province. All the Southern Province trainees were already employed, but some of the Northern Province trainees were not. Based only on the passage, which statement is FALSE?', options: ['All 40 trainees were already employed.', 'Fifteen of the trainees come from the Southern Province.', 'At least one trainee was not already employed.', 'Most of the Northern Province trainees were not employed.'], correct: 0, explanation: 'Some Northern Province trainees were not employed, so the first statement is false. 40 − 25 = 15, so the second is true, and the third follows from “some”. “Some” does not tell us whether this was most of them, so the last is cannot say, not false.' },
    { section: VER1, topic: VER1, stem: 'A manager reasons: “Every officer who attended the customer-care training received good feedback this year. Hakizimana received good feedback this year, so he must have attended the training.” What is wrong with this reasoning?', options: ['Nothing: the conclusion follows from what is stated.', 'It treats attending as the only route to good feedback.', 'It assumes that the training was offered free of charge.', 'It says that officers who attended did not receive good feedback.'], correct: 1, explanation: 'The manager knows that attending led to good feedback, not that only those who attended received it. Hakizimana could have received good feedback without attending, so the conclusion does not follow.' },

    { section: VER2, topic: VER2, stem: 'Thermometer is to temperature as scale is to:', options: ['height', 'distance', 'weight', 'pressure'], correct: 2, explanation: 'A thermometer is the instrument that measures temperature, and a scale is the instrument that measures weight.' },
    { section: VER2, topic: VER2, stem: 'Drought is to water as famine is to:', options: ['food', 'hunger', 'harvest', 'farmer'], correct: 0, explanation: 'A drought is a severe shortage of water, and a famine is a severe shortage of food. Hunger is a result of famine, not the thing in short supply.' },
    { section: VER2, topic: VER2, stem: 'Chapter is to book as clause is to:', options: ['signature', 'contract', 'lawyer', 'deadline'], correct: 1, explanation: 'A chapter is a part of a book, and a clause is a part of a contract. The relationship is part to whole.' },
    { section: VER2, topic: VER2, stem: 'Increase is to decrease as expand is to:', options: ['enlarge', 'extend', 'spread', 'contract'], correct: 3, explanation: 'Increase and decrease are opposites. The opposite of expand is contract; the other three options have meanings close to expand.' },
    { section: VER2, topic: VER2, stem: 'Choose the word that best completes the sentence: “The report was detailed, ___ it left out the project’s costs.”', options: ['because', 'therefore', 'yet', 'moreover'], correct: 2, explanation: 'The second part contrasts with the first: a detailed report would be expected to include costs. “Yet” signals that contrast; the other words signal cause, result or addition.' },
    { section: VER2, topic: VER2, stem: 'Put these sentences in the most logical order. (1) The committee therefore postponed the vote. (2) Several members had not received the report. (3) The vote was rescheduled for the following week.', options: ['1, 2, 3', '2, 1, 3', '3, 1, 2', '2, 3, 1'], correct: 1, explanation: 'Sentence 2 gives the cause, sentence 1 gives the result (“therefore”), and sentence 3 gives what happened next, so the order is 2, 1, 3.' },
    { section: VER2, topic: VER2, stem: 'What does this sentence mean? “Not all the reports were submitted on time.”', options: ['No report was submitted on time.', 'Most of the reports were submitted late.', 'Every report was submitted late.', 'At least one report was not submitted on time.'], correct: 3, explanation: '“Not all” only rules out every report being on time. It means at least one was not on time; it does not say how many, so it does not mean most or every report was late.' },
    { section: VER2, topic: VER2, stem: 'Which statement has the same meaning as this sentence? “Unless the form is signed, it will not be accepted.”', options: ['A form that is not signed will not be accepted.', 'Every signed form will be accepted.', 'A signature is optional if the form is complete.', 'Forms are signed only after they have been accepted.'], correct: 0, explanation: '“Unless signed, not accepted” means that an unsigned form is refused. A signature is necessary, but the sentence does not say it is enough on its own, so “every signed form will be accepted” does not follow.' },

    { section: VER3, topic: VER3, stem: '“The audit found a discrepancy between the cash book and the bank statement.” In this sentence, “discrepancy” is closest in meaning to:', options: ['an agreement', 'a mismatch', 'a delay', 'a payment'], correct: 1, explanation: 'A discrepancy is a difference between things that should match, here two financial records.' },
    { section: VER3, topic: VER3, stem: '“This directive supersedes the instructions issued last year.” In this sentence, “supersedes” is closest in meaning to:', options: ['replaces', 'repeats', 'explains', 'supports'], correct: 0, explanation: 'To supersede something is to take its place, so the new directive replaces last year’s instructions.' },
    { section: VER3, topic: VER3, stem: '“The director asked for a succinct summary of the findings.” In this sentence, “succinct” is closest in meaning to:', options: ['lengthy', 'confusing', 'brief and clear', 'carefully written'], correct: 2, explanation: 'Succinct means expressed clearly in few words.' },
    { section: VER3, topic: VER3, stem: '“The site visit is contingent on the road being repaired.” In this sentence, “contingent on” is closest in meaning to:', options: ['delayed by', 'opposed to', 'paid for by', 'dependent on'], correct: 3, explanation: 'If one thing is contingent on another, it will happen only if the other does. The visit depends on the road repair.' },
    { section: VER3, topic: VER3, stem: '“The officer was commended for her diligence during the data-collection exercise.” In this sentence, “diligence” is closest in meaning to:', options: ['careful, persistent effort', 'friendly manner', 'generous spending', 'rapid promotion'], correct: 0, explanation: 'Diligence means steady, careful effort in one’s work.' },
    { section: VER3, topic: VER3, stem: '“The committee agreed to defer the decision until its next meeting.” In this sentence, “defer” is closest in meaning to:', options: ['announce', 'reverse', 'postpone', 'delegate'], correct: 2, explanation: 'To defer a decision is to put it off to a later time, which fits “until its next meeting”.' },
    { section: VER3, topic: VER3, stem: '“Scanning the files will mitigate the risk of losing records in a fire.” In this sentence, “mitigate” is closest in meaning to:', options: ['remove completely', 'reduce', 'increase', 'record'], correct: 1, explanation: 'To mitigate a risk is to make it less severe or less likely. It does not mean removing the risk completely.' },
    { section: VER3, topic: VER3, stem: '“Her account of the meeting was corroborated by the official minutes.” In this sentence, “corroborated” is closest in meaning to:', options: ['contradicted', 'summarised', 'replaced', 'confirmed'], correct: 3, explanation: 'To corroborate an account is to support it with further evidence, so the minutes confirmed what she said.' },
  ],
};

// ───────────────────────────── Mock 3: Abstract and logical reasoning

const ABS1 = 'Series and odd one out';
const ABS2 = 'Logical deduction';
const ABS3 = 'Coding and arrangement';

const psychometricPrepMock3: TestDef = {
  country: 'RW',
  category: CATEGORY,
  profession: PROFESSION,
  slug: 'psychometric-test-preparation-mock-3',
  title: 'Psychometric Test Preparation — Mock Exam 3: Abstract and Logical Reasoning',
  summary: 'Original text-only practice questions on number and letter series, odd one out, syllogisms, coding and seating or order puzzles. For practice only: this is not a real or past exam paper.',
  free: false,
  difficulty: 'STANDARD',
  minutes: 90,
  sections: [{ name: ABS1 }, { name: ABS2 }, { name: ABS3 }],
  questions: [
    { section: ABS1, topic: ABS1, stem: 'What number comes next in the series? 3, 7, 15, 31, 63, ?', options: ['95', '125', '127', '131'], correct: 2, explanation: 'Each term is double the previous term plus 1: 3 × 2 + 1 = 7, 7 × 2 + 1 = 15, and so on. 63 × 2 + 1 = 127.' },
    { section: ABS1, topic: ABS1, stem: 'What number comes next in the series? 2, 6, 12, 20, 30, ?', options: ['40', '42', '44', '36'], correct: 1, explanation: 'The differences are 4, 6, 8, 10, so the next difference is 12. 30 + 12 = 42.' },
    { section: ABS1, topic: ABS1, stem: 'What number comes next in the series? 81, 27, 9, 3, ?', options: ['1', '0', '1.5', '2'], correct: 0, explanation: 'Each term is the previous term divided by 3. 3 ÷ 3 = 1.' },
    { section: ABS1, topic: ABS1, stem: 'What number comes next in the series? 5, 8, 6, 9, 7, 10, ?', options: ['11', '12', '9', '8'], correct: 3, explanation: 'The steps alternate between +3 and −2: 5, 8, 6, 9, 7, 10. The next step is −2, and 10 − 2 = 8.' },
    { section: ABS1, topic: ABS1, stem: 'What number comes next in the series? 1, 1, 2, 3, 5, 8, 13, ?', options: ['18', '20', '21', '26'], correct: 2, explanation: 'From the third term on, each term is the sum of the two before it. 8 + 13 = 21.' },
    { section: ABS1, topic: ABS1, stem: 'What letter comes next in the series? B, E, H, K, ?', options: ['N', 'M', 'L', 'O'], correct: 0, explanation: 'Each letter moves forward 3 places: B(2), E(5), H(8), K(11). The next is position 14, which is N.' },
    { section: ABS1, topic: ABS1, stem: 'What letter comes next in the series? Z, X, U, Q, ?', options: ['M', 'L', 'K', 'N'], correct: 1, explanation: 'The steps back increase by one each time: Z(26) −2 = X(24), −3 = U(21), −4 = Q(17), −5 = position 12, which is L.' },
    { section: ABS1, topic: ABS1, stem: 'What pair of letters comes next in the series? AB, DE, GH, JK, ?', options: ['LM', 'KL', 'NO', 'MN'], correct: 3, explanation: 'Each pair starts 3 letters after the start of the pair before: A(1), D(4), G(7), J(10), then position 13, which is M. The pair is MN.' },
    { section: ABS1, topic: ABS1, stem: 'Three of these numbers share a mathematical property that the fourth does not have. Which is the odd one out? 17, 19, 21, 23', options: ['17', '19', '21', '23'], correct: 2, explanation: '17, 19 and 23 are prime numbers. 21 is not prime, because 21 = 3 × 7.' },
    { section: ABS1, topic: ABS1, stem: 'Which is the odd one out? Litre, Metre, Kilometre, Centimetre', options: ['Litre', 'Metre', 'Kilometre', 'Centimetre'], correct: 0, explanation: 'Metre, kilometre and centimetre are units of length. A litre is a unit of volume.' },
    { section: ABS1, topic: ABS1, stem: 'Which letter group is the odd one out? ACE, BDF, GIK, HKM', options: ['ACE', 'BDF', 'GIK', 'HKM'], correct: 3, explanation: 'ACE, BDF and GIK each move forward 2 letters at every step. HKM moves forward 3 letters and then 2, so it breaks the pattern.' },
    { section: ABS1, topic: ABS1, stem: 'Three of these numbers are alike in a way that the fourth is not. Which is the odd one out? 25, 49, 63, 81', options: ['25', '63', '49', '81'], correct: 1, explanation: '25 = 5², 49 = 7² and 81 = 9² are perfect squares. 63 is not a perfect square, as it lies between 7² = 49 and 8² = 64.' },

    { section: ABS2, topic: ABS2, stem: 'All inspectors are officers. All officers are trained. Which statement must be true?', options: ['All trained people are inspectors.', 'Some officers are not trained.', 'All inspectors are trained.', 'No inspector is trained.'], correct: 2, explanation: 'Inspectors are within officers, and officers are within trained people, so all inspectors are trained. The reverse need not hold: there may be trained people who are not inspectors.' },
    { section: ABS2, topic: ABS2, stem: 'No auditors are suppliers. Some accountants are suppliers. Which statement must be true?', options: ['No accountant is an auditor.', 'Some accountants are not auditors.', 'Some auditors are accountants.', 'All suppliers are accountants.'], correct: 1, explanation: 'The accountants who are suppliers cannot be auditors, because no auditor is a supplier. So some accountants are not auditors. Other accountants may or may not be auditors, so the first and third statements do not have to be true.' },
    { section: ABS2, topic: ABS2, stem: 'Some drivers are mechanics. All mechanics are union members. Which statement must be true?', options: ['Some drivers are union members.', 'All drivers are union members.', 'All union members are mechanics.', 'No driver is a union member.'], correct: 0, explanation: 'The drivers who are mechanics are also union members, because all mechanics are. Nothing is known about the other drivers, so we cannot say that all drivers are members.' },
    { section: ABS2, topic: ABS2, stem: 'All files in the blue cabinet are closed. File 12 is closed. What follows?', options: ['File 12 is in the blue cabinet.', 'File 12 is not in the blue cabinet.', 'Whether File 12 is in the blue cabinet cannot be concluded.', 'Every closed file is in the blue cabinet.'], correct: 2, explanation: 'The rule says that blue-cabinet files are closed, not that all closed files are in the blue cabinet. File 12 could be in the blue cabinet or elsewhere, so no conclusion about its location follows.' },
    { section: ABS2, topic: ABS2, stem: 'If the report is late, the meeting is postponed. The meeting was not postponed. What follows?', options: ['The report was late.', 'The meeting was held later than usual.', 'The report was late, but the meeting went ahead.', 'The report was not late.'], correct: 3, explanation: 'A late report would have led to a postponed meeting. Since the meeting was not postponed, the report cannot have been late.' },
    { section: ABS2, topic: ABS2, stem: 'All of the unit’s cars are white. Some of the unit’s cars run on diesel. Which statement must be true?', options: ['Some white cars run on diesel.', 'All diesel cars are white.', 'All white cars belong to the unit.', 'No white car runs on diesel.'], correct: 0, explanation: 'The unit’s diesel cars are white, because all its cars are white, so some white cars run on diesel. Nothing is known about cars outside the unit.' },
    { section: ABS2, topic: ABS2, stem: 'One of Claire, Dan and Eric misfiled a document. Claire says, “I did not do it.” Dan says, “Claire did it.” Eric says, “I did not do it.” Exactly one of these statements is true. Who misfiled the document?', options: ['Claire', 'Dan', 'Cannot be determined', 'Eric'], correct: 3, explanation: 'If Claire did it, Dan and Eric both speak truly: two true statements. If Dan did it, Claire and Eric both speak truly: two true statements. If Eric did it, only Claire speaks truly: exactly one. So it was Eric.' },
    { section: ABS2, topic: ABS2, stem: 'All surveyors are engineers. Some engineers are consultants. Which conclusion must be true?', options: ['Some surveyors are consultants.', 'No surveyor is a consultant.', 'All engineers are consultants.', 'None of these conclusions must be true.'], correct: 3, explanation: 'The engineers who are consultants may or may not include any surveyors, so neither of the first two conclusions is certain. “Some engineers” does not mean all, so the third fails too.' },
    { section: ABS2, topic: ABS2, stem: 'If a request is urgent, it goes to the Director. If a request goes to the Director, it is logged in the red register. Today’s request is urgent. Which statement must be true?', options: ['Every request in the red register is urgent.', 'Today’s request is logged in the red register.', 'Today’s request does not go to the Director.', 'Only today’s request is urgent.'], correct: 1, explanation: 'Urgent means it goes to the Director, and going to the Director means it is logged in the red register. The rules run one way, so a logged request need not be urgent.' },

    { section: ABS3, topic: ABS3, stem: 'In a code, each letter is replaced by the next letter of the alphabet, so PLAN becomes QMBO. How is FILE written in this code?', options: ['GJMF', 'EHKD', 'GJLF', 'HKNG'], correct: 0, explanation: 'F → G, I → J, L → M, E → F, which gives GJMF.' },
    { section: ABS3, topic: ABS3, stem: 'In a code, WATER is written as RETAW. How is HOUSE written in this code?', options: ['EUSOH', 'ESOUH', 'ESUOH', 'HESUO'], correct: 2, explanation: 'The code writes the word backwards. HOUSE reversed is E-S-U-O-H, which gives ESUOH.' },
    { section: ABS3, topic: ABS3, stem: 'In a code, each letter takes its position in the alphabet (A = 1, B = 2, and so on), and a word’s value is the sum of its letters, so CAB = 6. What is the value of FACE?', options: ['14', '15', '16', '13'], correct: 1, explanation: 'F = 6, A = 1, C = 3, E = 5. 6 + 1 + 3 + 5 = 15. (Check: CAB = 3 + 1 + 2 = 6.)' },
    { section: ABS3, topic: ABS3, stem: 'In a code, ROAD is written as 18-15-1-4. How is LAND written in this code?', options: ['11-1-13-4', '12-1-13-4', '12-2-14-4', '12-1-14-4'], correct: 3, explanation: 'Each letter is replaced by its position in the alphabet: R = 18, O = 15, A = 1, D = 4. So L = 12, A = 1, N = 14, D = 4, which gives 12-1-14-4.' },
    { section: ABS3, topic: ABS3, stem: 'In a code, “bor lim” means “open file” and “lim tas” means “file report”. What is the code word for “report”?', options: ['bor', 'lim', 'tas', 'Cannot be determined'], correct: 2, explanation: '“File” is the only word in both phrases and “lim” is the only code word in both, so lim = file. The other code word in the second phrase must then mean “report”, so tas = report.' },
    { section: ABS3, topic: ABS3, stem: 'Five officers sit in a row, all facing the same way. A sits at the far left, and B sits immediately to the right of A. C does not sit at either end. D sits immediately to the left of E. Who sits in the middle seat?', options: ['B', 'C', 'D', 'E'], correct: 1, explanation: 'A is in seat 1 and B in seat 2. C, D and E take seats 3, 4 and 5. D and E must be adjacent with D on the left, so they are in 3-4 or 4-5. If they were in 3-4, C would be in seat 5, an end seat, which is not allowed. So D is in 4, E in 5 and C in the middle seat, 3.' },
    { section: ABS3, topic: ABS3, stem: 'P, Q, R and S each sit at one side of a square table, facing its centre. P sits opposite R. Q sits immediately to P’s right. Who sits immediately to R’s right?', options: ['P', 'Q', 'S', 'Cannot be determined'], correct: 2, explanation: 'Place P on the south side, facing north, so P’s right is east and Q sits on the east side. R sits on the north side, which leaves S on the west side. R faces south, so R’s right is west, which is S.' },
    { section: ABS3, topic: ABS3, stem: 'Five colleagues finished a task at different times. Asha finished before Bosco but after Chantal. Diane finished before Chantal. Eric finished after Bosco. Who finished third?', options: ['Asha', 'Bosco', 'Chantal', 'Diane'], correct: 0, explanation: 'Chantal is before Asha and Asha before Bosco. Diane is before Chantal and Eric is after Bosco. The full order is Diane, Chantal, Asha, Bosco, Eric, so Asha is third.' },
    { section: ABS3, topic: ABS3, stem: 'Kalisa is taller than Mugabo but shorter than Nshuti. Uwera is taller than Nshuti. Who is the second tallest of the four?', options: ['Nshuti', 'Kalisa', 'Uwera', 'Mugabo'], correct: 0, explanation: 'From tallest to shortest, the order is Uwera, Nshuti, Kalisa, Mugabo, so Nshuti is the second tallest.' },
  ],
};

// ───────────────────────────── Mock 4: Public service judgment

const PSJ1 = 'Integrity and conflict of interest';
const PSJ2 = 'Confidentiality and accountability';
const PSJ3 = 'Service to citizens and teamwork';

// The Order cited in explanations. See the sources at the top of this file.
const ETHICS_ORDER = 'Rwanda’s 2021 Presidential Order on professional ethics for public servants';

const psychometricPrepMock4: TestDef = {
  country: 'RW',
  category: CATEGORY,
  profession: PROFESSION,
  slug: 'psychometric-test-preparation-mock-4',
  title: 'Psychometric Test Preparation — Mock Exam 4: Public Service Judgment',
  summary: 'Original practice scenarios on integrity, conflict of interest, confidentiality, accountability, service to citizens and teamwork in a Rwandan public-service setting. For practice only: this is not a real or past exam paper.',
  free: false,
  difficulty: 'STANDARD',
  minutes: 90,
  sections: [{ name: PSJ1 }, { name: PSJ2 }, { name: PSJ3 }],
  questions: [
    { section: PSJ1, topic: PSJ1, stem: 'While your unit is evaluating bids, a bidding contractor sends a crate of drinks to your home with a note wishing you well. What is the most appropriate response?', options: ['Share the crate with colleagues at the office, so that nobody benefits personally.', 'Keep it, since the note asks for nothing, and score the bid strictly on merit.', 'Decline or return it, and inform your supervisor about it in writing.', 'Send a polite thank-you note and carry on scoring against the published criteria.'], correct: 2, explanation: `A gift from a bidder during an evaluation calls your objectivity into doubt, however it is used afterwards. ${ETHICS_ORDER} prohibits soliciting or accepting gifts outside listed purposes (Article 17) and requires refraining from gifts that can call independence into question (Article 8).` },
    { section: PSJ1, topic: PSJ1, stem: 'You are appointed to a tender evaluation panel and then see that your cousin’s company is one of the bidders. What should you do?', options: ['Disclose the relationship to the panel chair and step aside from this evaluation.', 'Stay on the panel and mark your cousin’s bid more strictly than the others.', 'Tell your cousin you cannot discuss the tender, and carry on scoring all the bids.', 'Withdraw from the panel on health grounds, so that the relationship stays private.'], correct: 0, explanation: `${ETHICS_ORDER} says a public servant must avoid any conflict of interest (Article 10), and failing to disclose one is a disciplinary fault (Article 29). Marking more strictly is still biased, and giving a false reason hides the problem instead of disclosing it.` },
    { section: PSJ1, topic: PSJ1, stem: 'At the end of an official visit, a foreign delegation presents you with a carved box in a formal ceremony, and refusing it would cause offence. It is not meant for your personal use. What should you do?', options: ['Refuse it on the spot, explaining that no gift may ever be accepted by a public servant.', 'Take it home as a souvenir, since it was given during official duties.', 'Keep it on your desk without any record, since its value is modest.', 'Accept it, then hand it to your institution with a letter stating its origin.'], correct: 3, explanation: `${ETHICS_ORDER} allows a gift for certain purposes, including respect of foreign culture, and requires the recipient to deliver it to the institution with a letter specifying its origin (Article 17).` },
    { section: PSJ1, topic: PSJ1, stem: 'You receive a wristwatch at a ceremony in recognition of an innovation you developed at work. The watch is clearly meant for your personal use. Under Rwanda’s 2021 Presidential Order on professional ethics, what should you do?', options: ['Keep it, because recognition for innovation is not treated as a gift at all under the Order.', 'Deliver it to your institution with a letter of origin; keep it only if its head approves.', 'Sell it and give the money to a local school, so that you gain nothing from it.', 'Keep it after your immediate colleagues have confirmed that they have no objection.'], correct: 1, explanation: `${ETHICS_ORDER} lists recognition for performance or innovation as an allowed purpose. The gift is delivered to the institution with a letter specifying its origin, and a gift for personal use may be retained upon approval by the head of the institution (Article 17).` },
    { section: PSJ1, topic: PSJ1, stem: 'Your supervisor asks you to use a project vehicle for their family errands at the weekend and to enter “field visit” in the logbook. What is the most appropriate response?', options: ['Do the errands, but write the true purpose of the trip in the logbook.', 'Do the errands and pay for the fuel yourself, so that the State bears no cost.', 'Decline: the vehicle is for official use and the logbook must be accurate.', 'Say nothing, and arrange not to be assigned that vehicle at weekends.'], correct: 2, explanation: `${ETHICS_ORDER} requires State assets to be handled purposefully (Article 6) and accurate information to be given to supervisors (Article 13). Respecting instructions does not extend to misusing a vehicle or entering a false record.` },
    { section: PSJ1, topic: PSJ1, stem: 'You see a colleague charging residents an unofficial fee to stamp their documents. What should you do?', options: ['Warn the colleague privately and treat the matter as closed if the charging stops.', 'Report what you saw through the proper internal channel without delay.', 'Wait until a resident files a formal complaint, so that there is evidence on record.', 'Post what you saw on social media, so that residents know not to pay.'], correct: 1, explanation: `${ETHICS_ORDER} requires a public servant to disclose fraud, corruption, nepotism or any other malpractice (Article 6). Not disclosing a fault you are aware of is itself a disciplinary fault (Article 28).` },
    { section: PSJ1, topic: PSJ1, stem: 'You work in your institution’s procurement unit and also own a stationery shop. The institution is about to buy stationery. What should you do?', options: ['Stay in the process, but abstain from the final decision on the stationery contract.', 'Register the bid in your spouse’s name, so that your own name does not appear.', 'Offer the lowest price, since saving public money outweighs any conflict.', 'Declare your interest in writing and stay out of any decision involving your shop.'], correct: 3, explanation: `${ETHICS_ORDER} says a public servant must avoid any conflict of interest (Article 10) and acts in the interests of public service instead of personal interest (Article 8). Disclosure plus staying out of the matter deals with the conflict; a spouse’s name only hides it.` },
    { section: PSJ1, topic: PSJ1, stem: 'You sit on a recruitment panel. A friend who has applied asks what topics the interview will cover. What should you do?', options: ['Refuse to discuss it, and tell the panel chair about the friendship.', 'Share only the broad topics, since most candidates could guess them anyway.', 'Say nothing to anyone, and simply mark your friend fairly on the day.', 'Leave the panel without giving a reason, and then help your friend to prepare.'], correct: 0, explanation: 'Any advance information gives one candidate an unfair advantage, and the friendship must be disclosed so that the panel can decide how to handle it. Fair marking alone leaves the conflict hidden.' },
    { section: PSJ1, topic: PSJ1, stem: 'You are a public servant newly appointed as a member of a tender committee. Under Rwanda’s 2021 law on declaration of assets, which organ receives your declaration?', options: ['The Rwanda Revenue Authority', 'The Office of the Auditor General', 'The Office of the Ombudsman', 'The Ministry of Public Service and Labour'], correct: 2, explanation: 'Law N° 55/2021 on declaration of assets covers public servants involved in public finance and State property, defined to include members of tender committees (Articles 2 and 3). The organ that receives declarations is the Office of the Ombudsman (Article 9).' },
    { section: PSJ1, topic: PSJ1, stem: 'A person at your service counter says they are a relative of your Director and asks to be served ahead of the queue. There is no urgency. What should you do?', options: ['Explain politely that everyone is served in turn, including them.', 'Serve them first, to avoid any awkwardness with your Director later.', 'Phone the Director first, to check whether the relationship is genuine.', 'Ask a colleague to attend to them quietly at another desk.'], correct: 0, explanation: `${ETHICS_ORDER} requires a public servant to treat all people equally and to be objective (Article 8). Whether the relationship is genuine makes no difference, so checking it would not help.` },

    { section: PSJ2, topic: PSJ2, stem: 'A journalist who is your friend asks for the list of successful candidates before your institution has published it. What should you do?', options: ['Share it off the record, on condition that your name is kept out of the story.', 'Confirm only the names your friend already has, without sending the full list.', 'Send it, since the list will become public within a few days anyway.', 'Decline, and point your friend to the official publication when it comes out.'], correct: 3, explanation: `${ETHICS_ORDER} requires a public servant to maintain confidentiality, with disclosure done in accordance with relevant laws (Article 10). Disclosing confidential information is listed as gross misconduct (Article 30).` },
    { section: PSJ2, topic: PSJ2, stem: 'A resident asks for your institution’s published list of service fees. A colleague tells you never to give documents to the public. What should you do?', options: ['Follow your colleague’s advice and ask the resident to write to the Minister.', 'Give the list, because the public may access information not protected by law.', 'State the fees orally, but refuse to let the resident see the document.', 'Ask why the resident wants it, and decide according to the reason given.'], correct: 1, explanation: `${ETHICS_ORDER} says a public servant recognises the public’s right of access to information, excluding information specifically protected by law (Article 12). A published fee list is not protected information.` },
    { section: PSJ2, topic: PSJ2, stem: 'You discover that, through your error, a folder of applicants’ personal details on a shared drive has been open to all staff for a week. What should you do?', options: ['Restrict access now, and tell your supervisor what happened so that it can be assessed.', 'Move the folder quietly and say nothing, since nobody appears to have opened it.', 'Delete the folder permanently, so that no copy can be seen again.', 'Email all staff, asking them to forget anything they may have read.'], correct: 0, explanation: `Stopping the exposure and reporting it lets the institution assess the harm. ${ETHICS_ORDER} expects a public servant to take responsibility for actions and be answerable for them (Article 5), and destroying work-related information is itself listed as gross misconduct (Article 30).` },
    { section: PSJ2, topic: PSJ2, stem: 'After a payment list has been approved and paid, you find that you entered RWF 40,000 too much for one beneficiary. What should you do?', options: ['Reduce that beneficiary’s next payment quietly, so that the totals balance.', 'Repay the RWF 40,000 from your own pocket and tell nobody.', 'Report the error to your supervisor promptly, and correct it properly.', 'Leave it for the auditors to find, because checking is their job.'], correct: 2, explanation: `${ETHICS_ORDER} expects a public servant to take responsibility for actions and to be answerable for omissions (Article 5). Quiet fixes leave the records wrong and the cause unexamined.` },
    { section: PSJ2, topic: PSJ2, stem: 'Your supervisor asks you to date a report last month, so that it appears to have met a deadline that was missed. What should you do?', options: ['Backdate it as instructed, because respecting a supervisor’s instructions is a duty.', 'Decline, keep the true date, and suggest explaining the delay in a covering note.', 'Backdate it, but keep a private note of the true date in case of an audit.', 'Leave the date blank and let your supervisor fill it in.'], correct: 1, explanation: `${ETHICS_ORDER} requires respect for a supervisor’s instructions and also accurate information to supervisors (Article 13), and it lists forgery as gross misconduct (Article 30). An instruction to falsify a date should be declined respectfully, with an honest way forward offered.` },
    { section: PSJ2, topic: PSJ2, stem: 'You supervise an officer and have seen evidence that the officer claimed allowances for a mission that never took place. What should you do?', options: ['Move the officer to another unit, so that the problem leaves your team.', 'Speak to the officer informally and keep the matter off the record.', 'Take no action, because the officer is close to retirement.', 'Report it through the proper channel, so that proceedings can follow.'], correct: 3, explanation: `Under ${ETHICS_ORDER}, a supervisor does not condone a disciplinary fault and is accountable for inaction on a fault he or she was aware of (Article 16). Fraud is listed as gross misconduct (Article 30).` },
    { section: PSJ2, topic: PSJ2, stem: 'You work at the Office of the Ombudsman. A friend asks what a neighbouring official wrote in their asset declaration. What should you do?', options: ['Refuse, as only its owner and those who receive it may know its contents.', 'Give only the total value, since no individual items of property would be exposed.', 'Share it, provided that your friend promises to keep it private.', 'Share it, because public officials have no privacy over their assets.'], correct: 0, explanation: 'Law N° 55/2021 on declaration of assets keeps declarations confidential, so that their contents are known only to their owners and those who receive them (Article 12). The limited exceptions are written requests by listed authorities in the interest of justice, and a friend’s curiosity is not one of them.' },
    { section: PSJ2, topic: PSJ2, stem: 'Your unit reached 70% of its quarterly target. A colleague suggests reporting 90%, because “next quarter will make up for it”. What should you do?', options: ['Report 90% as suggested, then work harder to close the gap next quarter.', 'Report the true 70%, explain the cause and propose corrective steps.', 'Show 70% in an annex, but 90% in the summary that managers read.', 'Leave the figure out of the report until the position improves.'], correct: 1, explanation: `${ETHICS_ORDER} requires accurate information to supervisors (Article 13) and lists providing inaccurate work information as a disciplinary fault (Article 29). Accurate figures allow managers to respond to the shortfall.` },
    { section: PSJ2, topic: PSJ2, stem: 'On a crowded bus, two colleagues start discussing the details of a resident’s land dispute that your office is handling. What is the most appropriate response?', options: ['Join in, to make sure that the details they mention are correct.', 'Stay silent now, and report them for disciplinary action tomorrow.', 'Quietly ask them to stop, and to continue the discussion at the office.', 'Move away, so that you are not associated with the conversation.'], correct: 2, explanation: 'The immediate concern is to stop a resident’s private matter being overheard. A quiet word does that straight away, while staying silent or moving away lets the disclosure continue.' },
    { section: PSJ2, topic: PSJ2, stem: 'To save a resident a trip, you are asked to take an official fee on your personal mobile money account and pay it in later. What should you do?', options: ['Accept it this once, and give the resident a handwritten receipt.', 'Ask a colleague to receive it on their phone, as a second person adds control.', 'Tell the resident that the fee is waived because of the distance.', 'Refuse, explain the official way to pay, and help them do it if you can.'], correct: 3, explanation: 'Public money should reach the institution only through its official payment channel, so that it can be traced. Personal accounts mix public and private funds, and an officer cannot simply waive a fee as a favour. Helping the resident pay correctly still serves them.' },

    { section: PSJ3, topic: PSJ3, stem: 'An elderly resident arrives 15 minutes before closing time with a form that is missing two details. What is the most appropriate response?', options: ['Ask them to return tomorrow, since forms cannot be handled so close to closing.', 'Explain what is missing, help as far as possible today and say what to bring next.', 'Accept the form as it is, and fill in the missing details yourself later.', 'Send them to a colleague who usually deals with elderly residents.'], correct: 1, explanation: `${ETHICS_ORDER} says a public servant must be at the service of citizens, be careful, diligent and polite, and provide efficient service (Article 7). Filling in details yourself risks an inaccurate record.` },
    { section: PSJ3, topic: PSJ3, stem: 'A resident is shouting at your desk because a document promised last week is still not ready. What is the most appropriate response?', options: ['Stay calm, listen, check the file and give a clear next step and date.', 'Promise it will be ready tomorrow, so that the resident calms down and leaves.', 'Call security at once, because shouting in the office is not acceptable.', 'Explain that the delay comes from another unit and that you cannot help.'], correct: 0, explanation: 'Listening and checking the facts addresses the actual problem and lowers the tension. A promise you cannot be sure of keeping stores up a worse complaint for later, and there is no sign of a threat that calls for security.' },
    { section: PSJ3, topic: PSJ3, stem: 'A resident who reads only Kinyarwanda is given a form printed only in English. What is the most appropriate response?', options: ['Ask them to come back with a relative who can read English.', 'Fill in the form for them and ask them to sign without reading it.', 'Explain each part in Kinyarwanda and help them complete it accurately.', 'Give them the form to take home and return whenever it is complete.'], correct: 2, explanation: 'The resident needs to understand what they are signing, and explaining the form in their language achieves that without sending them away. Signing unread is unsafe for both sides.' },
    { section: PSJ3, topic: PSJ3, stem: 'A resident who uses a wheelchair cannot reach your first-floor office, because the building has no lift. What is the most appropriate response?', options: ['Ask the resident to send someone else who can climb the stairs.', 'Give them an appointment for when a ramp may become available.', 'Ask them to write to the institution, so that the request is on record.', 'Go down to serve them, and raise the access problem with management.'], correct: 3, explanation: `${ETHICS_ORDER} requires treating all people equally without discrimination (Article 8) and serving beneficiaries with respect (Article 12). Going down solves today’s problem, and raising the issue helps the next resident too.` },
    { section: PSJ3, topic: PSJ3, stem: 'A resident brings you a request that belongs to another unit in your institution. What is the most appropriate response?', options: ['Find out which office handles it and guide them there.', 'Say that it is not your responsibility, and call the next person forward.', 'Keep the request and deal with it yourself, even though you lack the authority.', 'Tell them to ask at reception, without checking where it should go.'], correct: 0, explanation: 'The resident deals with one institution, not its internal divisions, so guiding them to the right office serves them properly. A public servant exercises authority only within its limits (Article 10 of the 2021 Order), so handling it yourself is not the answer.' },
    { section: PSJ3, topic: PSJ3, stem: 'A colleague falls ill three days before a joint report is due, and their part has not been started. What is the most appropriate response?', options: ['Submit only your own part, and note that the rest was your colleague’s job.', 'Write their part yourself and submit it under their name without telling anyone.', 'Tell your supervisor now, and agree how to share the work to meet the deadline.', 'Ask for a two-week extension before looking at what can be done in time.'], correct: 2, explanation: 'Raising the problem early lets the work be reassigned openly while there is still time. Submitting under a colleague’s name would misrepresent who did the work, and an extension should not be the first step before options have been looked at.' },
    { section: PSJ3, topic: PSJ3, stem: 'At a public meeting, a speaker thanks you personally for a project your whole unit delivered. What is the most appropriate response?', options: ['Accept the praise, since others can correct the speaker if they wish.', 'Thank the speaker, and make clear that it was your institution’s team effort.', 'Say nothing now, and mention the team in your next performance appraisal.', 'Ask the speaker afterwards to publish a written correction in the local media.'], correct: 1, explanation: `${ETHICS_ORDER} says a public servant refrains from personalising a public institution’s success (Article 10). A short, gracious correction on the spot is proportionate.` },
    { section: PSJ3, topic: PSJ3, stem: 'Two colleagues in your unit argue so often that residents at the counter have begun to notice, and service is slowing down. What is the most appropriate response?', options: ['Take the side of the colleague you believe is right, to end it quickly.', 'Ignore it, because personal disagreements are not your business at work.', 'Tell residents who ask about it that both colleagues are at fault.', 'Speak with them privately, and involve the supervisor if it continues.'], correct: 3, explanation: `${ETHICS_ORDER} expects colleagues to ensure a good working relationship for efficient service provision (Article 15). A private word comes first, and the supervisor can step in if that does not resolve it.` },
    { section: PSJ3, topic: PSJ3, stem: 'A new colleague keeps making small errors in a register that you both use. What is the most appropriate response?', options: ['Correct the errors silently each time, so that the colleague is not embarrassed.', 'Report the colleague in writing for discipline without speaking to them first.', 'Show them the correct method, and tell the supervisor if the errors continue.', 'Warn other colleagues not to trust any entry the new colleague has made.'], correct: 2, explanation: 'Small errors by a new colleague most likely point to a gap in knowledge, so showing the method fixes the cause. Silent correction leaves the cause in place, and involving the supervisor remains the next step if the problem continues.' },
    { section: PSJ3, topic: PSJ3, stem: 'Your Sector plans to move a market, and vendors have started hearing rumours. You are asked how to handle communication with them. What do you advise?', options: ['Consult the vendors, explain the plan and reasons, and take their views into account.', 'Say nothing until the final decision is made, to avoid any unnecessary debate.', 'Share the plan only with vendors’ leaders, and ask them to keep it private.', 'Announce the move on the day, to keep vendors from organising against it.'], correct: 0, explanation: `${ETHICS_ORDER} requires openness about decisions, and involving stakeholders and the public in preparing and implementing Government decisions (Article 9).` },
  ],
};

// ───────────────────────────── Mock 5: the real test format (21 questions)
//
// Unlike Mocks 1-4, this mock follows the format of MIFOTRA's e-recruitment psychometric test and uses sample questions
// reported from a candidate's walkthrough of that test (the "Public Relations and Communication Officer" test, level
// 4.II): 21 questions in four domains (critical thinking, problem solving, time management, clear and effective
// communication), mostly workplace scenarios plus a few true/false and fill-in items, with 3 marks for the scenario
// questions, 2 for the short ones and 4 for the last. The walkthrough's printed keys were re-checked: question 3 is a
// time-zone sum (six hours behind, so 1:30 pm becomes 7:30 pm for you) and question 14 follows the walkthrough's own
// explanation (reassess and adjust the plan). The matching item is turned into a multiple-choice question because the
// exam player has no matching format. The real test also has a countdown per question; here there is one timer.

